import { View, Text, StyleSheet } from "react-native";
import { registerRootComponent } from "expo";

const TAGS = ["Гар утас", "Компьютер", "Гэр ахуй", "Хувцас", "Гоо сайхан", "Спорт", "Ном"];

function App() {
  return (
    <View nativeID="wrap" style={styles.wrap}>
      {TAGS.map((t, i) => (
        <Text key={i} testID="tag" style={styles.tag}>{t}</Text>
      ))}
      {/* энд бичнэ үү: wrap-д мөр таслалт нэм */}
    </View>
  );
}

const styles = StyleSheet.create({
  wrap: { flexDirection: "row", gap: 8, padding: 16 },
  tag: { backgroundColor: "#eef2ff", color: "#3730a3", paddingHorizontal: 14, paddingVertical: 8, borderRadius: 999 },
});

registerRootComponent(App);

